"""Pipeline proof tests (uses fixtures generated by CLI)."""

from __future__ import annotations

from pathlib import Path

import pytest

from talk_to_type.config import Settings
from talk_to_type.constants import data_home
from talk_to_type.models_download import ensure_vosk_model, vosk_model_dir
from talk_to_type.pipeline import run_wav_file
from talk_to_type.tools.test_pipeline_cli import generate_fixtures, pad_long_wav


@pytest.fixture(scope="module")
def settings() -> Settings:
    s = Settings()
    if not vosk_model_dir().is_dir():
        s.vosk_model_dir = str(ensure_vosk_model())
    return s


@pytest.fixture(scope="module")
def fixtures(tmp_path_factory) -> Path:
    dest = data_home() / "test-fixtures"
    if not list(dest.glob("*.wav")):
        paths = generate_fixtures(dest)
        pad_long_wav(dest / "05_long_25s.wav", 25.0)
        assert len(paths) == 5
    return dest


def test_five_wavs_never_empty(settings: Settings, fixtures: Path):
    first_times: list[float] = []
    for wav in sorted(fixtures.glob("*.wav")):
        result = run_wav_file(settings, wav)
        assert result.never_empty, wav.name
        assert result.text.strip()
        if result.first_partial_ms is not None:
            first_times.append(result.first_partial_ms)
    assert first_times, "expected at least one partial"
    assert min(first_times) < 700.0, f"first partial too slow: {min(first_times)}"